		name	pcmanexe

_IVT		segment	at 0

_ivt_vectors	dd	256 dup (?)

_IVT		ends

_BIOS_DATA	segment	at 40h

		db	7ch dup (?)
boot_flag	dw	?

_BIOS_DATA	ends

_CGA		segment	at 0b800h
_CGA		ends

_BIOS_TOP	segment	at 0ffffh

_bios_reset	label	far

_BIOS_TOP	ends

DGROUP		group	CONST,_DATA,_BSS

_TEXT		segment	para public 'CODE'
		assume	cs:_TEXT,ds:DGROUP,es:nothing,ss:STACK

_main		proc	far

		; Load ES with the CGA's framebuffer address
		mov	ax,seg _CGA
		mov	es,ax
		assume	es:_CGA

		; Turn the speaker on
		mov	al,4fh
		out	61h,al
		mov	al,0b6h
		out	43h,al

		; Set mode 320x200, 4 colours
		mov	ax,4
		int	10h

		; Change the palette to bright and cyan/magenta/white
		mov	dx,3d9h
		mov	al,10h
		out	dx,al

		; Delay 3 ticks
;		mov	dl,3
;		call	delay

		; Draw the logo
		cld
		mov	di,150h		; Start at 32,4
		mov	bx,-12		; Prepare to backtrack
blit_next_char:	mov	cx,17h		; Copy 17 rows
		mov	dx,1ff7h	; Distance to odd rows (2000h - 9)
		mov	bp,0e047h	; Distance back to even (-1fb9h)

blit_loop:	mov	si,[font_tbl_1_ptr]
		mov	ax,[si]
		cmp	al,-1
		je	font_done
		dec	ah
		mov	byte ptr [si+1],ah
		or	ah,ah
		jnz	font_repeated
		mov	si,2
		add	word ptr [font_tbl_1_ptr],si
font_repeated:	xor	ah,ah
		mov	si,ax
		shl	ax,1 ; * 2
		shl	ax,1 ; * 4
		shl	ax,1 ; * 8
		add	ax,si ; * 9
		mov	si,offset font_tbl_2
		add	si,ax
		movsw
		movsw
		movsw
		movsw
		movsb
      db 3,0fah;add	di,dx		; Advance to next row
		xchg	dx,bp
		loop	blit_loop

		sub	di,2370h	; Position of next character
		add	di,[bx+offset font_widths]	; Initially 4dah
		add	bx,2		; Go to next entry in table
		jnz	blit_next_char	; Draw next character
font_done:
		mov	si,offset font_widths
		mov	bp,112h
next_music:	mov	ah,0
		int	1ah
    db 8bh,0dah;mov	bx,dx
timer_loop:	mov	ah,0
		int	1ah
    db 3bh,0dah;cmp	bx,dx
		jz	timer_loop
		; Check if a key has been pressed
		mov	ah,1
		int	16h
		jz	music_loop
		; Check if it was the Esc key
		call	chk_esc_key
		; Check if it was the Enter key
		cmp	al,13h
		jnz	music_loop
		neg	negged_flag	; Unclear what this does
music_loop:	lodsw

		cmp	negged_flag,0
		jg	l0082
		call	l0F50
		jmp	l0088
l0082:		out	42h,al
    db 8ah,0c4h;mov	al,ah
		out	42h,al
l0088:		sub	bp,2
		jnz	next_music

;		mov	dl,3
;		call	delay
		mov	cx,5
		mov	si,offset opening_msg
l0098:		cld
		lodsw
    db 8bh,0d0h;mov	dx,ax
		mov	bh,0
		mov	ah,2
		int	10h
l00A2:		lodsb
		cmp	al,0
		jz	l00B0

		mov	bx,2
		mov	ah,0eh
		int	10h
		jmp	l00A2
l00B0:		loop	l0098

		mov	flag_2,1
		call	chk_esc_key
		cmp	ah,24h
		jz	l00DE

		mov	flag_2,0

		ret

l00D0:
		db	03Ch,020h                          ; cmp al,020h                         
l00D2:
		db	074h,00Ah                          ; jz 0xde                             
l00D4:
		db	03Ch,013h                          ; cmp al,013h                         
l00D6:
		db	075h,0DAh                          ; jnz 0xb2                            
l00D8:
		db	0F6h,01Eh,0A0h,02Fh                ; neg byte [0x2fa0]                   
l00DC:
		db	0EBh,0D4h                          ; jmp 0xb2                            
l00DE:
		db	0C7h,006h,024h,02Dh,000h,000h      ; mov word [0x2d24],0x0               
l00E4:
		db	0C6h,006h,0F0h,006h,003h           ; mov byte [0x6f0],0x3                
l00E9:
		db	0C7h,006h,0F1h,006h,000h,000h      ; mov word [0x6f1],0x0                
l00EF:
		db	006h                               ; push es                             
l00F0:
		db	01Eh                               ; push ds                             
l00F1:
		db	007h                               ; pop es                              
l00F2:
		db	0BFh,07Eh,02Fh                     ; mov di,0x2f7e                       
l00F5:
		db	0B9h,005h,000h                     ; mov cx,0x5                          
l00F8:
		db	0FCh                               ; cld                                 
l00F9:
		db	0B0h,000h                          ; mov al,0x0                          
l00FB:
		db	0F3h,0AAh                          ; rep stosb                           
l00FD:
		db	007h                               ; pop es                              
l00FE:
		db	0E8h,01Dh,000h                     ; call 011he                          
l0101:
		db	0B0h,002h                          ; mov al,0x2                          
l0103:
		db	0E6h,042h                          ; out byte 042h,al                    
l0105:
		db	032h,0C0h                          ; xor al,al                           
l0107:
		db	0E6h,042h                          ; out byte 042h,al                    
l0109:
		db	0BEh,078h,006h                     ; mov si,067h8                        
l010C:
		db	0B9h,002h,000h                     ; mov cx,0x2                          
l010F:
		db	0EBh,087h                          ; jmp 098h                            

_main		endp

; Sleeps. Specify the number of seconds in DL.
delay		proc	near

		mov	cx,0
delay_l:	loop	delay_l
		mov	cx,0
		dec	dl
		jnz	delay_l
		ret

delay		endp

l0F50		proc	near

		mov	ax,2
		out	42h,al
		mov	al,ah
		out	42h,al
		ret

l0F50		endp

chk_esc_key	proc	near

		mov	ah,0		; Get keypress
		int	16h
		cmp	al,1bh		; Check for Esc key
		jnz 	no_esc_pressed	; Quit if pressed
		ret

; Turns off the speaker.
reset_spkr:	mov	al,4dh		; Silence the speaker
		out	61h,al
;		mov	ax,3		; Reset to 80x25 colour text mode
;		int	10h

; Exits. (Performs a warm reboot.)
_exit		label	near

		mov	ax,4c00h
		int	21h
		hlt

		mov	ax,seg _BIOS_DATA
		mov	ds,ax
		assume	ds:_BIOS_DATA
		xor	ax,ax
		mov	boot_flag,ax
		jmp	_bios_reset

no_esc_pressed:	ret

chk_esc_key	endp

_TEXT		ends
_DATA		segment	para public 'DATA'

		db	429h dup (?)

